import json
import os

PATH = os.path.expanduser('~/.tasktally.json')


def load(path=PATH):
    if not os.path.exists(path):
        return []
    with open(path, encoding='utf-8') as fh:
        return json.load(fh)


def save(tasks, path=PATH):
    with open(path, 'w', encoding='utf-8') as fh:
        json.dump(tasks, fh, indent=2)
